  void CmtChooseImportOption(long dialog,long qt,int groupIndex,int choiceIndex,string expectedName){
   IAccessible general;var import=CmtImportGroup(dialog,qt,true,out general);var group=CmtChild(import,groupIndex);var item=CmtChild(group,choiceIndex);CmtField(item,groupIndex==3?44:45,expectedName,true);
