  public CmtAccountImportSnapshot SetCmtAccountImport(long dialog,long qt,string media,string mode,bool deleteAfter){
   if(Array.IndexOf(new[]{"U盘","U盘 2","SD 卡"},media)<0||Array.IndexOf(new[]{"覆盖","附加"},mode)<0)throw new ArgumentException("Finite original account-import options required");
   var before=InspectCmtAccountImport(dialog,qt);if(before.Media!=media)CmtChooseImportOption(dialog,qt,1,Array.IndexOf(new[]{"U盘","U盘 2","SD 卡"},media),media);
   var afterMedia=InspectCmtAccountImport(dialog,qt);if(afterMedia.Media!=media||afterMedia.Description!=before.Description||afterMedia.TriggerOnRelease!=before.TriggerOnRelease)throw new InvalidOperationException("Original import-media readback differs");
   if(afterMedia.ImportMode!=mode)CmtChooseImportOption(dialog,qt,2,Array.IndexOf(new[]{"覆盖","附加"},mode),mode);
   var afterMode=InspectCmtAccountImport(dialog,qt);if(afterMode.ImportMode!=mode||afterMode.Media!=media||afterMode.Description!=before.Description||afterMode.TriggerOnRelease!=before.TriggerOnRelease)throw new InvalidOperationException("Original import-mode readback differs");
   if(afterMode.DeleteAfterImport!=deleteAfter)CmtChooseImportOption(dialog,qt,3,0,"导入用户账号后删除文件");
   var after=InspectCmtAccountImport(dialog,qt);if(after.Media!=media||after.ImportMode!=mode||after.DeleteAfterImport!=deleteAfter||after.Description!=before.Description||after.TriggerOnRelease!=before.TriggerOnRelease)throw new InvalidOperationException("Original User Accounts import readback differs");return after;
  }
  public CmtAccountImportSnapshot SelectCmtAccountImportAction(long dialog,long qt){
   var general=CmtGeneral(dialog,qt,true);var property=CmtChild(general,4);CmtField(property,20,"属性",true);if(property.accChildCount!=3)throw new InvalidOperationException("Original function type group changed");
   var type=CmtChild(property,2);CmtField(type,46,"属性 Down",true);string value=type.get_accValue(0);
   if(value=="窗口"){
    if(type.get_accDefaultAction(0)!="ShowMenu")throw new InvalidOperationException("Original function type ShowMenu action required");
    var list=CmtChild(type,0);CmtField(list,33,null,false);if(list.accChildCount!=7)throw new InvalidOperationException("Original seven function types changed");
