    type.accDoDefaultAction(0);long popup=0;DateTime deadline=DateTime.UtcNow.AddSeconds(3);do{popup=CmtPopup(dialog,qt,type);if(popup!=0)break;Thread.Sleep(50);}while(DateTime.UtcNow<deadline);
    if(popup==0)throw new InvalidOperationException("Owned function-type popup absent");
    var root=RootImportPopup(popup);var choices=CmtChild(root,0);CmtField(choices,33,null,false);if(choices.accChildCount!=7)throw new InvalidOperationException("Function-type popup list changed");
    var selected=CmtChild(choices,5);CmtField(selected,34,"导入用户数据",true);if(String.IsNullOrEmpty(selected.get_accDefaultAction(0)))throw new InvalidOperationException("Function-type popup item has no original native action");
    R bounds;if(!GetWindowRect(new IntPtr(popup),out bounds))throw new InvalidOperationException("Function-type popup bounds absent");int x,y,w,h;selected.accLocation(out x,out y,out w,out h,0);
    if(w<3||h<3||x<bounds.l||y<bounds.t||x+w>bounds.r||y+h>bounds.b)throw new InvalidOperationException("Import-data menu item outside owned popup");
    if(requireForeground&&GetForegroundWindow().ToInt64()!=popup)throw new InvalidOperationException("Function-type popup must be owned foreground");
    P point=new P{x=x+w/2,y=y+h/2};if(!ScreenToClient(new IntPtr(popup),ref point)||point.x<0||point.y<0||point.x>32767||point.y>32767)throw new InvalidOperationException("Function-type popup client point invalid");
    var packed=new IntPtr((point.y<<16)|(point.x&65535));if(!PostMessageW(new IntPtr(popup),0x201,new UIntPtr(1),packed)||!PostMessageW(new IntPtr(popup),0x202,UIntPtr.Zero,packed))throw new InvalidOperationException("Owned import-data selection refused");
    deadline=DateTime.UtcNow.AddSeconds(3);do{general=CmtGeneral(dialog,qt,false);property=CmtChild(general,4);type=CmtChild(property,2);if(type.get_accValue(0)=="导入用户数据")break;Thread.Sleep(50);}while(DateTime.UtcNow<deadline);
    if(type.get_accValue(0)!="导入用户数据")throw new InvalidOperationException("Original import-data function type did not commit");
   }else if(value!="导入用户数据")throw new InvalidOperationException("Existing function type is outside observed import conversion");
   IAccessible changed;var import=CmtImportGroup(dialog,qt,true,out changed);var kind=CmtChild(import,0);CmtField(kind,20,"导入用户数据",true);
   var first=CmtChild(kind,0);var account=CmtChild(kind,1);CmtField(first,45,"导入 e-mail 设置和联系人",false);CmtField(account,45,"导入用户账户",true);
   if((Convert.ToInt32(account.get_accState(0))&16)==0){CmtChooseImportOption(dialog,qt,0,1,"导入用户账户");}
   return InspectCmtAccountImport(dialog,qt);
  }
  static IAccessible RootImportPopup(long popup){var iid=new Guid("618736E0-3C3D-11CF-810C-00AA00389B71");IAccessible root;int hr=AccessibleObjectFromWindow(new IntPtr(popup),0xFFFFFFFC,ref iid,out root);if(hr!=0||root==null||Role(root,0)!=19||root.accChildCount!=1)throw new InvalidOperationException("Owned function-type popup root changed");return root;}
  static void SameCmtNavigation(CmtWindowNavigationSnapshot before,CmtWindowNavigationSnapshot after,bool targetChanged,bool descriptionChanged){if(before.Hwnd!=after.Hwnd||before.TriggerOnRelease!=after.TriggerOnRelease||before.Items.Length!=after.Items.Length||(!targetChanged&&before.Value!=after.Value)||(!descriptionChanged&&before.Description!=after.Description))throw new InvalidOperationException("Unrequested cMT navigation fields changed.");for(int i=0;i<before.Items.Length;i++)if(before.Items[i]!=after.Items[i])throw new InvalidOperationException("Unrequested cMT target list changed.");}
